    public boolean canJump(int[] nums) {
        if (nums.length == 1) {
            return true;
        }
        boolean possible = false;
        int curr = nums[0];
        for (int j = curr; j >= 1; j--) {
            possible = possible || recursive(nums, j);
        }

//        System.out.println(possible);
//        System.out.println();


        DP.clear();
        return possible;
    }

    public boolean recursive(int[] nums, int index) {
//        System.out.println(DP);
        if (DP.get(index) != null){
            return DP.get(index);
        }
//        System.out.printf("index %d, from recur: %b\n", index, fromRecur);
        if (index >= nums.length-1) {
//            System.out.printf("index %dxxx\n", index);
            return true;
        }
//        if (nums[index] == 0) {
//            return false;
//        }
        boolean possible = false;
        int curr = nums[index];
        for (int j = index+curr; j >= index+1; j--) {
            possible = possible || recursive(nums, j);
        }

        DP.put(index, possible);

        return possible;
    }

    public static void main(String[] args) {
        new JumpGame();
    }
